cat > Cargo.toml <<'EOF'
[package]
name = "hashprobe"
version = "0.1.0"
edition = "2021"

[dependencies]
serde = { version = "1", features = ["derive"] }
bincode = "1"
postcard = { version = "1", features = ["use-std"] }
sha2 = "0.10"
blake3 = "1"
serde_json = "1"
rmp-serde = "1"
EOF
mkdir src
cat > src/main.rs <<'EOF'
use serde::Serialize;
use sha2::{Digest, Sha256};

fn sha256_hex(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    format!("{:x}", hasher.finalize())
}

fn blake3_hex(bytes: &[u8]) -> String {
    blake3::hash(bytes).to_hex().to_string()
}

#[derive(Serialize)]
struct BasicCard { question: String, answer: String }
#[derive(Serialize)]
enum CardContentTuple { Basic(BasicCard), Cloze(ClozeCard) }
#[derive(Serialize)]
enum CardContentStruct {
    Basic { question: String, answer: String },
    Cloze { text: String, start: usize, end: usize },
}
#[derive(Serialize)]
struct ClozeCard { text: String, start: usize, end: usize }
#[derive(Serialize)]
struct TextOnly { text: String }

fn show<T: Serialize>(label: &str, value: &T) {
    let json = serde_json::to_vec(value).unwrap();
    let bin = bincode::serialize(value).unwrap();
    let post = postcard::to_allocvec(value).unwrap();
    let msg = rmp_serde::to_vec(value).unwrap();
    println!("{label} json sha {}", sha256_hex(&json));
    println!("{label} json bl3 {}", blake3_hex(&json));
    println!("{label} bin sha {}", sha256_hex(&bin));
    println!("{label} bin bl3 {}", blake3_hex(&bin));
    println!("{label} post sha {}", sha256_hex(&post));
    println!("{label} post bl3 {}", blake3_hex(&post));
    println!("{label} msg sha {}", sha256_hex(&msg));
    println!("{label} msg bl3 {}", blake3_hex(&msg));
}

fn main() {
    let basic = BasicCard { question: "x".into(), answer: "y".into() };
    let basic_tuple = CardContentTuple::Basic(BasicCard { question: "x".into(), answer: "y".into() });
    let basic_struct = CardContentStruct::Basic { question: "x".into(), answer: "y".into() };
    let cloze = ClozeCard { text: "foo bar".into(), start: 0, end: 2 };
    let cloze_tuple = CardContentTuple::Cloze(ClozeCard { text: "foo bar".into(), start: 0, end: 2 });
    let cloze_struct = CardContentStruct::Cloze { text: "foo bar".into(), start: 0, end: 2 };
    let text_only = TextOnly { text: "foo bar".into() };
    show("basic", &basic);
    show("basic_tuple", &basic_tuple);
    show("basic_struct", &basic_struct);
    show("cloze", &cloze);
    show("cloze_tuple", &cloze_tuple);
    show("cloze_struct", &cloze_struct);
    show("text_only", &text_only);
    println!("str sha {}", sha256_hex("foo bar".as_bytes()));
    println!("str bl3 {}", blake3_hex("foo bar".as_bytes()));
}
EOF
